<script setup lang="ts">
import { ref, computed, nextTick, watch, onMounted, onUnmounted } from 'vue'
import { Activity, ArrowUpRight, Box, Check, ChevronRight, Copy, Eye, EyeOff, Globe2, LayoutDashboard, LogOut, Radio, RefreshCw, Server, Settings2, ShieldCheck, Users, X, Zap } from 'lucide-vue-next'
type Service={id:string;endpointId:string;name:string;kind:string;status:string;version:string;revision:number;updatedAt:string;role:string;runtimeId:string;config:Record<string,string>;members:{userId:string;role:string}[]}
const data=ref<{endpoints:any[];runtimes:any[];services:Service[];events:any[];userId:string;storage?:string}>({endpoints:[],runtimes:[],services:[],events:[],userId:''})
const logged=ref(false), email=ref(''), password=ref(''), page=ref('overview'), selected=ref('hy2'), filter=ref(''), notice=ref(''), error=ref(''), busy=ref(false), revealed=ref(false), connected=ref(false), editing=ref(false), draft=ref<Record<string,string>>({}), revision=ref(0)
let source:EventSource|undefined, timer:ReturnType<typeof setTimeout>
let restoreFocus:HTMLElement|null=null
watch(editing,async open=>{if(open){restoreFocus=document.activeElement as HTMLElement;await nextTick();document.querySelector<HTMLInputElement>('.modal input')?.focus()}else{await nextTick();restoreFocus?.focus()}})
const active=computed(()=>data.value.services.find(s=>s.id===selected.value)); const services=computed(()=>data.value.services.filter(s=>s.name.toLowerCase().includes(filter.value.toLowerCase())))
async function api(path:string,body?:unknown){const r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const d=await r.json();if(r.status===401&&path!=='login'){source?.close();logged.value=false;data.value.services=[];revealed.value=false;editing.value=false;connected.value=false}if(!r.ok) throw new Error(d.error||'请求失败');return d}
async function load(){data.value=await api('snapshot')}
function stream(){source?.close();source=new EventSource('/api/events');source.onopen=()=>connected.value=true;source.onmessage=()=>{load().catch(e=>error.value=e.message)};source.onerror=()=>connected.value=false}
async function login(){busy.value=true;error.value='';try{await api('login',{username:email.value,password:password.value});password.value='';await load();logged.value=true;stream()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function logout(){try{await api('logout',{});source?.close();logged.value=false;data.value.services=[];revealed.value=false}catch(e:any){error.value=e.message}}
function toast(s:string){notice.value=s;clearTimeout(timer);timer=setTimeout(()=>notice.value='',3000)}
function choose(s:Service){selected.value=s.id;revealed.value=false;editing.value=false;page.value='services'}
async function action(s:Service,kind:string,body:unknown={}){if(kind==='stop'&&!confirm('停止 '+s.name+'？'))return;busy.value=true;error.value='';try{await api('services/'+s.id+'/'+kind,body);await load();editing.value=false;toast('已更新')}catch(e:any){error.value=e.message}finally{busy.value=false}}
function edit(){if(!active.value)return;error.value='';draft.value={...active.value.config};revision.value=active.value.revision;editing.value=true}
function uri(s:Service){const c=s.config;if(s.kind==='hysteria2')return `hysteria2://${encodeURIComponent(c.credential)}@${c.host}:${c.port}/?sni=${encodeURIComponent(c.sni)}#lisw-demo`;return `vless://${c.credential}@${c.host}:${c.port}?encryption=none&security=reality&type=tcp&sni=${encodeURIComponent(c.sni)}&pbk=${encodeURIComponent(c.publicKey)}&sid=${c.shortId}&flow=${c.flow}#lisw-demo`}
async function copy(s:Service){try{await navigator.clipboard.writeText(uri(s));toast('已复制')}catch{error.value='无法访问剪贴板，请显示配置后手动复制。'}}
function time(v:string){return new Date(v).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}
function trapFocus(e:KeyboardEvent){if(e.key!=='Tab')return;const el=e.currentTarget as HTMLElement;const nodes=Array.from(el.querySelectorAll<HTMLElement>('button:not(:disabled),input,select,[tabindex="0"]'));const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}
onMounted(async()=>{try{await load();logged.value=true;stream()}catch{}});onUnmounted(()=>{source?.close();clearTimeout(timer)})
</script>

<template>
<div v-if="!logged" class="auth-shell">
 <section class="auth-story"><a class="brand"><span class="brand-icon"><Radio :size="22"/></span>lisw<span class="brand-dot">.</span></a><div class="orbit"><Globe2 :size="100"/><span><Zap :size="20"/> Hysteria 2</span><span><ShieldCheck :size="20"/> VLESS</span></div></section>
 <section class="auth-form"><h2>欢迎回来</h2><form @submit.prevent="login"><label>账号<input v-model="email" placeholder="用户名或邮箱" autocomplete="username" required></label><label>密码<input v-model="password" type="password" required autocomplete="current-password"></label><button class="primary wide" :disabled="busy">{{busy?'登录中…':'登录'}} <ArrowUpRight :size="18"/></button></form><p v-if="error" class="error" role="alert">{{error}}</p></section>
</div>
<div v-else class="workspace">
 <aside class="sidebar"><a class="brand"><span class="brand-icon"><Radio :size="22"/></span>lisw<span class="brand-dot">.</span></a><div class="space-switch"><div class="avatar">S</div><div><b>Snacking's space</b></div><ChevronRight :size="15"/></div><span class="nav-label">工作空间</span><nav><button :class="{current:page==='overview'}" @click="page='overview'"><LayoutDashboard :size="19"/>总览</button><button :class="{current:page==='services'}" @click="page='services'"><Box :size="19"/>我的服务<span class="nav-count">{{data.services.length}}</span></button><button :class="{current:page==='members'}" @click="page='members'"><Users :size="19"/>成员与权限</button><button :class="{current:page==='activity'}" @click="page='activity'"><Activity :size="19"/>更新记录</button></nav><div class="sidebar-bottom"><button class="profile" @click="logout"><span class="avatar small">{{data.userId==='admin'?'S':'F'}}</span><span><b>{{data.userId==='admin'?'Snacking':'Friend'}}</b><small>{{data.userId==='admin'?'空间管理员':'服务用户'}}</small></span><LogOut :size="17"/></button></div></aside>
 <main><header class="topbar"><span>工作空间 <ChevronRight :size="13"/> {{({overview:'总览',services:'我的服务',members:'成员与权限',activity:'更新记录'} as any)[page]}}</span><span class="live"><i :class="{offline:!connected}"></i>{{connected?'实时同步中':'正在重连'}}</span></header>
 <div class="content">
 <div v-if="error" class="error" role="alert">{{error}}<button class="text-button" @click="error=''">关闭</button></div>
 <section class="page-heading"><div><h1>{{({overview:'总览',services:'你的服务',members:'成员与权限',activity:'更新记录'} as any)[page]}}</h1></div><button class="secondary" :disabled="busy" @click="load().then(()=>toast('已获取最新状态')).catch(e=>error=e.message)"><RefreshCw :size="16"/>刷新状态</button></section>
 <template v-if="page==='overview'">
 <div class="stats"><article><span>在线服务 <Box :size="17"/></span><strong>{{data.services.filter(s=>s.status==='running').length}}<small> / {{data.services.length}}</small></strong></article><article><span>连接入口 <Globe2 :size="17"/></span><strong>{{data.endpoints.length.toString().padStart(2,'0')}}</strong></article><article><span>空间成员 <Users :size="17"/></span><strong>{{new Set(data.endpoints.flatMap(e=>e.members.map((m:any)=>m.userId))).size.toString().padStart(2,'0')}}</strong></article></div>
 <div class="section-title"><h2>你的连接入口 <span>{{data.endpoints.length.toString().padStart(2,'0')}}</span></h2></div>
 <article v-for="e in data.endpoints" :key="e.id" class="endpoint"><div class="endpoint-art"><Globe2 :size="78" :stroke-width="1"/><span class="map-dot"></span><small>LOS ANGELES · US</small></div><div class="endpoint-info"><div class="pill"><i/> 主入口</div><h2>{{e.name}}</h2><p><code>{{e.address}}</code><span>{{e.region}}</span></p><div class="tags"><span><Server :size="13"/> 本机部署</span><span><Box :size="13"/> {{data.services.filter(s=>s.endpointId===e.id).length}} 个服务</span><span><Users :size="13"/> {{e.members.length}} 位成员</span></div></div><button class="round-button" aria-label="查看入口服务" @click="page='services'"><ArrowUpRight :size="23"/></button></article>
 </template>
 <template v-if="page==='overview'||page==='services'">
 <div class="section-title"><h2>服务 <span>{{data.services.length.toString().padStart(2,'0')}}</span></h2><input class="search" v-model="filter" aria-label="搜索服务" placeholder="搜索服务…"></div>
 <div class="service-grid"><article v-for="s in services" :key="s.id" class="service-card" :class="{chosen:page==='services'&&selected===s.id}"><div class="card-top"><span class="service-icon" :class="s.kind"><Zap v-if="s.kind==='hysteria2'" :size="25"/><ShieldCheck v-else :size="25"/></span><span class="status" :class="{stopped:s.status!=='running'}"><i/>{{s.status==='running'?'运行中':'已停止'}}</span></div><button class="service-title" @click="choose(s)">{{s.name}} <ArrowUpRight :size="18"/></button><div class="service-meta"><span>{{data.endpoints.find(e=>e.id===s.endpointId)?.name}}</span><span>{{s.role==='admin'?'管理员':'用户'}}</span></div><footer><span>配置 v{{s.revision}} · {{time(s.updatedAt)}}</span><button class="text-button" @click="choose(s)">查看配置 <ChevronRight :size="14"/></button></footer></article></div><p v-if="!services.length" class="empty">没有匹配的服务。</p>
 <article v-if="page==='services'&&active" class="detail"><div class="section-title"><div><h2>{{active.name}} <span>配置 v{{active.revision}}</span></h2></div><button class="secondary" @click="copy(active)"><Copy :size="16"/>复制连接链接</button></div><div class="config-grid"><div v-for="(v,k) in active.config" :key="k"><label>{{k}}</label><code>{{k==='credential'&&!revealed?'••••••••••••••••':v}}</code></div></div><div class="actions"><button class="secondary" @click="revealed=!revealed"><EyeOff v-if="revealed" :size="16"/><Eye v-else :size="16"/>{{revealed?'隐藏凭据':'显示凭据'}}</button><template v-if="active.role==='admin'"><button class="secondary" :disabled="busy" @click="edit"><Settings2 :size="16"/>编辑配置</button><button class="secondary" :disabled="busy" @click="action(active,'upgrade')"><RefreshCw :size="16"/>模拟升级</button><button class="secondary" :class="{danger:active.status==='running'}" :disabled="busy" @click="action(active,active.status==='running'?'stop':'start')">{{active.status==='running'?'停止服务':'启动服务'}}</button></template></div></article>
 </template>
 <template v-if="page==='members'"><article class="detail" v-for="e in data.endpoints" :key="e.id"><h2>{{e.name}} · 入口权限</h2><div v-for="m in e.members" :key="m.userId" class="member"><span class="avatar">{{m.userId[0].toUpperCase()}}</span><b>{{m.userId}}</b><span>{{m.role==='admin'?'Endpoint 管理员':'Endpoint 用户'}}</span></div></article><article class="detail" v-for="s in data.services" :key="s.id"><h2>{{s.name}}</h2><div v-for="m in s.members" :key="m.userId" class="member"><Users :size="18"/><b>{{m.userId}}</b><span>{{m.role==='admin'?'服务管理员':'服务用户'}}</span></div></article></template>
 <template v-if="page==='overview'||page==='activity'"><div class="section-title"><h2>最近动态</h2><button v-if="page==='overview'" class="text-button" @click="page='activity'">全部记录 <ChevronRight :size="14"/></button></div><article class="activity-list"><div v-for="e in data.events.slice(0,page==='overview'?3:100)" :key="e.id" class="event"><span class="event-icon"><Activity :size="17"/></span><div><b>{{e.service}}</b><p>{{({start:'启动了服务',stop:'停止了服务',config:'更新了连接配置',upgrade:'完成了模拟升级'} as any)[e.action]||e.action}}</p></div><time>{{time(e.at)}}</time></div></article></template>
 </div></main>
</div>
<div v-if="notice" class="toast" role="status"><Check :size="18"/>{{notice}}</div>
<div v-if="editing&&active" class="modal-backdrop" @click.self="editing=false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="edit-title" @keydown.esc="editing=false" @keydown="trapFocus"><div class="section-title"><h2 id="edit-title">编辑连接配置</h2><button class="round-button" aria-label="关闭" @click="editing=false"><X :size="20"/></button></div><form @submit.prevent="action(active!,'config',{config:draft,revision})"><label v-for="(_,k) in draft" :key="k">{{k}}<input v-model="draft[k]" :autofocus="k==='host'"></label><p v-if="error" class="error" role="alert">{{error}}</p><div class="actions"><button type="button" class="secondary" @click="editing=false">取消</button><button class="primary" :disabled="busy">{{busy?'保存中…':'保存配置'}}</button></div></form></section></div>
</template>
